/**
 * Cloudflare Worker entry: the OpenNext app plus Cron Triggers.
 * The cron schedules in wrangler.jsonc call the same protected routes the
 * Vercel crons used, so queue/job logic is unchanged.
 */
// @ts-ignore — generated by `opennextjs-cloudflare build`
import app from "../.open-next/worker.js";

type Env = { CRON_SECRET?: string; APP_URL?: string };

const ROUTES: Record<string, string> = {
  "* * * * *": "/api/worker/drain", // inbound message queue — every minute
  "0 * * * *": "/api/worker/jobs",  // scheduled jobs — hourly
};

export default {
  fetch: app.fetch,

  async scheduled(event: { cron: string }, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }) {
    const path = ROUTES[event.cron];
    if (!path) return;
    const base = env.APP_URL ?? "https://leadra.internal";
    const req = new Request(new URL(path, base), {
      headers: { authorization: `Bearer ${env.CRON_SECRET ?? ""}` },
    });
    ctx.waitUntil(
      app.fetch(req, env, ctx).then(async (res: Response) => {
        if (!res.ok) console.error("cron_failed", path, res.status, (await res.text()).slice(0, 200));
      }),
    );
  },
};
